ution":"Low to moderate; COMELEC enforcement was institutionally independent, though the executive publicly supported enforcement.","contrary_evidence":["Filed cases do not establish complete detection, impartiality, or final adjudication of election offenses."]},{"evidence_id":"E021","claim":"Online political expression remained possible, but disinformation, red-tagging, harassment, cyberattacks, criminal libel, and website or platform restrictions impaired independent digital information and political participation.","publisher":"Freedom House","publication_date":"2023","source_confidence":"medium","period_fit":"target_period_with_inherited_context","ruler_attribution":"Moderate; administration-linked agencies and inherited legal tools were relevant, but platform actions and private disinformation networks were also significant.","contrary_evidence":["No nationwide internet shutdown was identified; civil society, fact-checkers, and independent online outlets continued to operate."]},{"evidence_id":"E022","claim":"CPJ reported 53 press-freedom violations during Marcos’s first year and three journalists murdered in connection with their work, while justice remained uncertain in the Mabasa case.","publisher":"Committee to Protect Journalists","publication_date":"2023-05-18","source_confidence":"medium","period_fit":"first_year_of_marcos_presidency_including_2023","ruler_attribution":"Moderate; no presidential order is shown, but the government was responsible for investigation, protection, and press-safety policy.","contrary_evidence":["CPJ described Marcos’s public tone as less hostile to media than Duterte’s and noted that private media remained active."]},{"evidence_id":"E038","claim":"The Philippine Commission on Human Rights recorded 93 alleged extrajudicial-killing cases, 35 torture cases, and 12 enforced-disappearance cases in 2023.","publisher":"cdn1.chr.gov.ph","publication_date":"unknown_not_exposed_by_source","source_confidence":"unknown_not_recorded","period_fit":"unknown_not_recorded","ruler_attribution":"unknown_not_recorded","contrary_evidence":[]},{"evidence_id":"E039","claim":"Human Rights Watch reported that drug-related killings, arbitrary arrests, disappearances, red-tagging, and politically controversial prosecutions continued during Marcos’s first year, with limited accountability.","publisher":"www.hrw.org","publication_date":"unknown_not_exposed_by_source","source_confidence":"unknown_not_recorded","period_fit":"unknown_not_recorded","ruler_attribution":"unknown_not_recorded","contrary_evidence":[]},{"evidence_id":"E040","claim":"Ferdinand R. Marcos Jr. held the Philippine presidency throughout 2023 and exercised executive authority through national policy orders, subject to constitutional and institutional constraints.","publisher":"Presidential Communications Office","publication_date":"2023","source_confidence":"high","period_fit":"target_period","ruler_attribution":"High","contrary_evidence":[]},{"evidence_id":"E053","claim":"The Supreme Court held that COMELEC election-administration powers are constitutionally defined and statutorily limited, while Congress retained broader authority over election postponement.","publisher":"Supreme Court of the Philippines","publication_date":"2023-06-27","source_confidence":"high","period_fit":"target_period","ruler_attribution":"Low to moderate; mainly evidence of institutional constraint.","contrary_evidence":["COMELEC commissioners are presidential appointees and appointment safeguards remain limited."]},{"evidence_id":"E054","claim":"COMELEC administered the October 30, 2023 synchronized Barangay and Sangguniang Kabataan elections under a published legal and operational calendar.","publisher":"Commission on Elections, Philippines","publication_date":"2023","source_confidence":"high","period_fit":"target_period","ruler_attribution":"Moderate","contrary_evidence":["Vote buying, political violence, and local dynastic influence impaired equal competition in some areas."]},{"evidence_id":"E055","claim":"CMFR reported 59 political-violence incidents involving barangay officials and candidates through September 20, 2023, while later police reporting identified 96 election-related incidents during the election period.","publisher":"Center for Media Freedom and Responsibility","publication_date":"2023","source_confidence":"medium","period_fit":"target_period","ruler_attribution":"Low to moderate","contrary_evidence":["COMELEC and police described many areas as generally peaceful and verified fewer incidents than initial reports."]},{"evidence_id":"E056","claim":"Bulatlat remained subject to an inherited website-blocking order during 2023 and faced red-tagging, platform restriction, legal costs, and major traffic decline; a local court prohibited blocking pending final judgment.","publisher":"Reuters Institute for the Study of Journalism","publication_date":"2023-08-11","source_confidence":"high","period_fit":"target period with inherited order","ruler_attribution":"Moderate to high for failure to lift or reverse inherited blocking; low for original order.","contrary_evidence":["The outlet continued operating through mirrors and reader support."]},{"evidence_id":"E057","claim":"The Philippines remained electorally competitive but was constrained by dynasties, vote buying, disinformation, high campaign costs, political violence, red-tagging, criminal cases against critics, media attacks, and weak safeguards.","publisher":"Freedom House","publication_date":"2023","source_confidence":"medium","period_fit":"target period with structural context","ruler_attribution":"Moderate for administration-era pressure; lower for inherited structures.","contrary_evidence":["Multiple parties, open elections, civil society, independent media, and constraining courts remained active."]}]}
{"iso3":"RUS","ruler_name":"Vladimir Putin","coverage":[{"methodology_id":"4B.1","status":"partially_covered","evidence_ids":["E001","E005","E006","E009","E030","E031","E032"],"reason":"Contains restored reviewed evidence."},{"methodology_id":"4B.2","status":"partially_covered","evidence_ids":["E030","E031","E032","E033","E034","E036"],"reason":"Contains restored reviewed evidence."},{"methodology_id":"4B.3","status":"partially_covered","evidence_ids":["E009","E032","E033","E034","E035","E036"],"reason":"Contains restored reviewed evidence."},{"methodology_id":"4B.4","status":"partially_covered","evidence_ids":["E030","E031","E033","E034"],"reason":"Contains restored reviewed evidence."},{"methodology_id":"4B.5","status":"partially_covered","evidence_ids":["E030","E031","E032","E036"],"reason":"Contains restored reviewed evidence."},{"methodology_id":"4B.6","status":"partially_covered","evidence_ids":["E005","E032","E033","E034","E035"],"reason":"Contains restored reviewed evidence."},{"methodology_id":"4B.7","status":"partially_covered","evidence_ids":["E036"],"reason":"Contains restored reviewed evidence."},{"methodology_id":"4B.8","status":"research_blocked","evidence_ids":[],"reason":"Formatter supplied no explicit researcher coverage disposition."},{"methodology_id":"4B.9","status":"partially_covered","evidence_ids":["E006","E033","E034","E035"],"reason":"Contains restored reviewed evidence."},{"methodology_id":"4B.10","status":"partially_covered","evidence_ids":["E030","E035","E036"],"reason":"Contains restored reviewed evidence."}],"evidence":[{"evidence_id":"E001","claim":"Putin was President throughout 2023 and exercised decisive influence over foreign policy, military strategy, senior security appointments, and the legislative agenda in an authoritarian institutional environment.","publisher":"Freedom House","publication_date":"2023","source_confidence":"high","period_fit":"target_period_2023","ruler_attribution":"Direct institutional attribution to Putin’s presidency.","contrary_evidence":[]},{"evidence_id":"E005","claim":"OVD-Info recorded 2,830 administrative discrediting cases and 794 people in anti-war criminal cases by December 2023, alongside coercion affecting journalists and activists.","publisher":"OVD-Info","publication_date":"2023-12-18","source_confidence":"medium","period_fit":"target_period_2023","ruler_attribution":"National legal and security policy; implementation distributed across agencies and regions.","contrary_evidence":["Formal courts and official procedures continued to operate."]},{"evidence_id":"E006","claim":"Russia expanded wartime coercive controls through electronic military summonses, unified military registration, harsher sabotage and treason penalties, and broader military-disinformation restrictions.","publisher":"OVD-Info","publication_date":"2023-12-18","source_confidence":"medium","period_fit":"target_period_2023","ruler_attribution":"National legislative and security policy.","contrary_evidence":["Authorities described the measures as wartime security controls."]},{"evidence_id":"E009","claim":"Russia’s 2023 political environment severely restricted meaningful competition through speech and extremism laws, pressure on independent organizations and media, and repression of opposition activity.","publisher":"Freedom House","publication_date":"2023","source_confidence":"high","period_fit":"target_period_2023","ruler_attribution":"National political and legal environment under Putin’s presidency.","contrary_evidence":["Some opposition, exile, and informal civic activity persisted."]},{"evidence_id":"E030","claim":"Russia held 4,295 election campaigns on 10 September 2023, but Golos assessed that citizens’ electoral rights had significantly worsened and that conditions for fully free competition were absent.","publisher":"Golos","publication_date":"2023-09","source_confidence":"medium","period_fit":"target_period_2023","ruler_attribution":"National electoral conditions and dominant-party system; local irregularities require separate attribution.","contrary_evidence":["Some opposition candidates and more competitive regional contests remained."]},{"evidence_id":"E031","claim":"The municipal filter and political collusion sharply limited genuine competition in gubernatorial elections, with opposition registration often dependent on incumbent-party or regional-administration cooperation.","publisher":"Golos","publication_date":"2023-09-04","source_confidence":"medium","period_fit":"target_period_2023","ruler_attribution":"National electoral design and regional administrative practice; Putin attribution is policy-level.","contrary_evidence":["The filter is formally presented as a local-support qualification mechanism."]},{"evidence_id":"E032","claim":"Incumbents and regional authorities held an information advantage through controlled media and administrative voter mobilization, while public discussion and competition were limited.","publisher":"Golos","publication_date":"2023-09-07","source_confidence":"medium","period_fit":"target_period_2023","ruler_attribution":"Regional administrative practice and national political incentives; direct personal involvement not established.","contrary_evidence":["Some regions retained more meaningful competition."]},{"evidence_id":"E033","claim":"Putin signed amendments restricting journalists at election-commission meetings, limiting recording at polling stations, and barring campaign materials on blocked online resources.","publisher":"Meduza","publication_date":"2023-11-14","source_confidence":"high","period_fit":"target_period_2023_governing_2024_election","ruler_attribution":"Direct presidential signature and federal legal policy.","contrary_evidence":["Officials described restrictions as necessary because of security conditions in new territories."]},{"evidence_id":"E034","claim":"Russia continued using false-information and discreditation charges in 2023 to prosecute peaceful expression, including Kara-Murza’s 25-year sentence.","publisher":"Human Rights Watch","publication_date":"2024","source_confidence":"high","period_fit":"target_period_2023","ruler_attribution":"Federal legislation, prosecution, and judicial policy; individual presidential ordering not shown.","contrary_evidence":["Authorities characterized charges as national-security offenses."]},{"evidence_id":"E035","claim":"Censorship forced many independent Russian media outlets to close, leave the country, or change operations, restricting independent information available to citizens.","publisher":"Reporters Without Borders","publication_date":"2023-2024","source_confidence":"medium","period_fit":"target_period_2023_with_inherited_conditions","ruler_attribution":"Federal censorship, registration, and media policy.","contrary_evidence":["Exiled and online outlets continued independent reporting."]},{"evidence_id":"E036","claim":"Authorities targeted Navalny’s movement, Open Russia, Vesna, Memorial, independent media, and civil-society organizations through extremist, undesirable-organization, and other legal mechanisms.","publisher":"Amnesty International","publication_date":"2023-01-23","source_confidence":"medium","period_fit":"target_period_2023_with_inherited_conditions","ruler_attribution":"Federal legal and prosecutorial policy; not every designation is personally attributable.","contrary_evidence":["Some groups continued abroad and informal civic networks persisted."]}]}

